<template>
  <span
    class="thumbnail-picture thumbnail-empty thumbnail-processing"
    :style="{
      width: emptyWidth + 'px',
      'min-width': emptyWidth + 'px',
      height: emptyHeight + 'px'
    }"
    v-if="isProcessing"
  />

  <span
    class="thumbnail-picture thumbnail-empty"
    :style="{
      width: emptyWidth + 'px',
      'min-width': emptyWidth + 'px',
      height: emptyHeight + 'px'
    }"
    :title="$t('preview.broken')"
    v-else-if="isBroken"
  />

  <a
    class="thumbnail-wrapper thumbnail-picture"
    target="_blank"
    :style="{
      width: emptyWidth + 'px',
      'min-width': emptyWidth + 'px',
      height: emptyHeight + 'px',
      cursor: noPreview ? 'default' : 'zoom-in'
    }"
    role="button"
    tabindex="0"
    @click="onClicked"
    @keydown.enter.prevent="onClicked"
    @keydown.space.prevent="onClicked"
    v-else-if="isPreview && withLink"
  >
    <img
      class="thumbnail-picture"
      loading="lazy"
      :key="thumbnailKey"
      :src="thumbnailPath"
      :style="imgStyle"
      :width="width || ''"
      alt=""
    />
  </a>

  <img
    v-else-if="isPreview && !withLink"
    class="thumbnail-picture"
    loading="lazy"
    :key="thumbnailKey"
    :src="thumbnailPath"
    :style="imgStyle"
    alt=""
  />

  <span
    :class="{
      'thumbnail-picture': true,
      'thumbnail-empty': true,
      square: square
    }"
    :style="imgStyle"
    v-else
  >
  </span>
</template>

<script setup>
import { computed, watch } from 'vue'
import { useStore } from 'vuex'

import { usePreviewFileStatus } from '@/composables/previewFileStatus'

const store = useStore()

const props = defineProps({
  entity: {
    default: () => ({}),
    type: Object
  },
  square: {
    default: false,
    type: Boolean
  },
  width: {
    default: null,
    type: Number
  },
  height: {
    default: null,
    type: Number
  },
  maxWidth: {
    default: null,
    type: Number
  },
  maxHeight: {
    default: null,
    type: Number
  },
  noPreview: {
    default: false,
    type: Boolean
  },
  emptyHeight: {
    default: 30,
    type: Number
  },
  emptyWidth: {
    default: 50,
    type: Number
  },
  previewFileId: {
    default: null,
    type: String
  },
  previewFileStatus: {
    type: String,
    default: null
  },
  withLink: {
    default: true,
    type: Boolean
  }
})

const previewFileId = computed(
  () => props.previewFileId || props.entity?.preview_file_id
)

const { isBroken, isProcessing, reload, reloadQuery } = usePreviewFileStatus(
  previewFileId,
  () => props.previewFileStatus
)

const isPreview = computed(() => previewFileId.value?.length > 0)

const imgStyle = computed(() => {
  const style = {}
  if (props.emptyWidth) {
    style['max-width'] = props.emptyWidth + 'px'
    style['min-width'] = props.emptyWidth + 'px'
  } else if (props.maxWidth) {
    style['max-width'] = props.maxWidth + 'px'
  } else if (props.width) {
    style.width = props.width + 'px'
    style['min-width'] = props.width + 'px'
  }
  if (props.emptyHeight) {
    style['max-height'] = props.emptyHeight + 'px'
    style['min-height'] = props.emptyHeight + 'px'
  } else if (props.maxHeight) {
    style['max-height'] = props.maxHeight + 'px'
  } else if (props.height) {
    style.height = props.height + 'px'
  }
  return style
})

const thumbnailPath = computed(() => {
  const variant = props.square
    ? 'thumbnails-square'
    : props.width && props.width > 150
      ? 'previews'
      : 'thumbnails'
  const fileName = `${previewFileId.value}.png${reloadQuery.value}`
  return `/api/pictures/${variant}/preview-files/${fileName}`
})

const thumbnailKey = computed(() => `thumbnail-${previewFileId.value}`)

const onClicked = () => {
  if (props.noPreview) return
  store.commit('SHOW_PREVIEW_FILE', previewFileId.value)
}

watch(() => props.previewFileId, reload)

watch(() => props.entity?.preview_file_id, reload)

watch(
  () => props.previewFileStatus,
  (status, previousStatus) => {
    // The browser may have cached the 404 it got while the variants were
    // being built.
    if (previousStatus === 'processing' && status === 'ready') reload()
  }
)
</script>

<style lang="scss" scoped>
.dark {
  table .thumbnail-picture.thumbnail-empty {
    background-color: $dark-grey-lighter;
    border-color: $dark-grey-light;
  }

  .thumbnail-picture,
  span.thumbnail-empty {
    background-color: $dark-grey-light;
    border-color: $dark-grey;
  }
}

.thumbnail-picture {
  border-radius: 4px;
  margin: 0;
}

// The background longhands leave the processing shimmer gradient alone.
span.thumbnail-empty {
  background-color: $white-grey;
  display: block;
  margin: 0;
}

.thumbnail-picture.square {
  width: 100px;
  height: 100px;
}

table .thumbnail-picture.thumbnail-empty {
  background-color: $white-grey;
  border: 1px solid $light-grey;
  margin: 0;
}

table .thumbnail-wrapper {
}

table .thumbnail-picture {
  background-color: black;
  border: 0;
  margin: 0;
  padding: 0;
}

.thumbnail-wrapper {
  padding: 0;
  border: 0;
  border-radius: 4px;
  display: inline-block;
}

// The variants are still being built: a slow shimmer reads as "on its
// way", where the plain empty block reads as "no preview at all".
.thumbnail-processing {
  background-image: linear-gradient(
    100deg,
    rgba(255, 255, 255, 0) 35%,
    rgba(255, 255, 255, 0.65) 50%,
    rgba(255, 255, 255, 0) 65%
  );
  background-repeat: no-repeat;
  background-size: 250% 100%;
  animation: thumbnail-processing-shimmer 1.6s ease-in-out infinite;
}

.dark .thumbnail-processing {
  background-image: linear-gradient(
    100deg,
    rgba(255, 255, 255, 0) 35%,
    rgba(255, 255, 255, 0.12) 50%,
    rgba(255, 255, 255, 0) 65%
  );
}

@keyframes thumbnail-processing-shimmer {
  from {
    background-position: 175% 0;
  }
  to {
    background-position: -75% 0;
  }
}

// Respect a reader who asked the system for less movement.
@media (prefers-reduced-motion: reduce) {
  .thumbnail-processing,
  .dark .thumbnail-processing {
    animation: none;
    background-image: none;
    opacity: 0.6;
  }
}
</style>
